-- EMPTY disposable loopback fixture only. Identity/auth/storage adapters are not hosted services.
CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
CREATE TYPE public.app_role AS ENUM ('admin','entrepreneur','user');
CREATE TABLE public.user_roles(user_id uuid,role app_role,PRIMARY KEY(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(uuid,app_role) RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM user_roles WHERE user_id=$1 AND role=$2) $$;
CREATE TABLE public.jsc_companies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text,legal_name text,address text,phone text,email text,created_at timestamptz DEFAULT now());
GRANT SELECT ON public.jsc_companies TO authenticated; GRANT ALL ON public.jsc_companies TO service_role;
ALTER TABLE public.jsc_companies ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.jsc_company_members(company_id uuid REFERENCES jsc_companies(id),user_id uuid,role text,full_name text,email text,is_active boolean DEFAULT true,archived_at timestamptz);
GRANT SELECT ON public.jsc_company_members TO authenticated; GRANT ALL ON public.jsc_company_members TO service_role;
ALTER TABLE public.jsc_company_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY own ON public.jsc_company_members FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY own ON public.jsc_companies FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM jsc_company_members m WHERE m.company_id=id AND m.user_id=auth.uid()));
GRANT USAGE ON SCHEMA auth,public TO authenticated;
CREATE SCHEMA storage;
CREATE TABLE storage.objects(bucket_id text,name text);
CREATE FUNCTION storage.foldername(text) RETURNS text[] LANGUAGE sql AS $$ SELECT string_to_array($1,'/') $$;
CREATE FUNCTION storage.extension(text) RETURNS text LANGUAGE sql AS $$ SELECT lower(substring($1 from '\.([^./]+)$')) $$;
CREATE TABLE public.jsc_trucks(id uuid PRIMARY KEY);
GRANT SELECT ON public.jsc_trucks TO authenticated; GRANT ALL ON public.jsc_trucks TO service_role;
ALTER TABLE public.jsc_trucks ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.ent_crm_files(id uuid PRIMARY KEY,company_id uuid,title text,file_name text,mime_type text,size_bytes int,archived_at timestamptz);
GRANT SELECT ON public.ent_crm_files TO authenticated; GRANT ALL ON public.ent_crm_files TO service_role;
ALTER TABLE public.ent_crm_files ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.ent_crm_file_links(id uuid PRIMARY KEY,file_id uuid,owner_id uuid,owner_type text,company_id uuid,client_visible boolean);
GRANT SELECT ON public.ent_crm_file_links TO authenticated; GRANT ALL ON public.ent_crm_file_links TO service_role;
ALTER TABLE public.ent_crm_file_links ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.ent_crm_services(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid,label text,unit text,price numeric,inclusions text,exclusions text,archived_at timestamptz);
GRANT SELECT ON public.ent_crm_services TO authenticated; GRANT ALL ON public.ent_crm_services TO service_role;
ALTER TABLE public.ent_crm_services ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.ent_crm_templates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid,name text,trade text,lines jsonb,inclusions text,exclusions text,conditions text,archived_at timestamptz);
GRANT SELECT,INSERT ON public.ent_crm_templates TO authenticated; GRANT ALL ON public.ent_crm_templates TO service_role;
ALTER TABLE public.ent_crm_templates ENABLE ROW LEVEL SECURITY;